/* Driver for the multi-module link test: instantiate A, register it under the
 * name B imports from, instantiate B, and call across the boundary.
 *
 * This is the shape a .wast file has -- several modules in one program, wired
 * by name at instantiation -- so it is also the shape the spec harness needs.
 */
#include "../../rt/warm_rt.h"

extern const ModuleDesc a_module;
extern const ModuleDesc b_module;
/* Generated by test/gen_link_wide.py: B's shape with two thousand globals in
 * front of its imports, so the { code, instance } pair for an imported
 * function sits past the reach of a scaled load immediate and the address has
 * to be materialised -- with the call's arguments already in their registers,
 * which is what makes the scratch register the compiler picks there matter. */
extern const ModuleDesc c_module;

/* The CLI harness in the runtime refers to this; a driver replaces the
 * harness but not the reference. */
const ModuleDesc warmc_module = { 0 };


static void out(const char *s) {
  const char *p = s;
  while (*p) p++;
  warmc_rt_write(1, s, (usz)(p - s));
}

static void put_i32(int v) {
  char buf[16];
  int i = 16;
  unsigned u = v < 0 ? (unsigned)(-(v + 1)) + 1u : (unsigned)v;
  if (!u) buf[--i] = '0';
  while (u) { buf[--i] = (char)('0' + (u % 10)); u /= 10; }
  if (v < 0) buf[--i] = '-';
  warmc_rt_write(1, buf + i, (usz)(16 - i));
}

static u64 call(WarmInstance *inst, const char *name, u64 arg, int nargs) {
  const ExportDesc *e = warmc_find_export(inst, name);
  if (!e) { out("missing export "); out(name); out("\n"); return 0; }
  u64 iargs[8] = { 0 }, fargs[WARMC_FARGS_WORDS] = { 0 };
  u64 ret[WARMC_RETBUF_WORDS] = { 0 };
  if (nargs) iargs[0] = arg;
  /* Not `inst`: an export may name a function another module defines, and
   * that one has to be entered with the instance that defines it. */
  FuncRef fr = warmc_export_func(inst, e);
  warmc_invoke(fr.code, (WarmInstance *)fr.instance, iargs, fargs, ret);
  return e->nresults ? ret[WARMC_RET_X0] : 0;
}

static void show(const char *label, u64 v) {
  out(label);
  out("=");
  put_i32((int)(u32)v);
  out("\n");
}

static int drive(int argc, char **argv);

/* Defining the hook keeps the runtime's default out of the link, and with it
 * the CLI harness's claim on argv. */
int (*warmc_driver_hook)(int, char **) = drive;

static int drive(int argc, char **argv) {
  (void)argc; (void)argv;

  WarmInstance *a = warmc_instantiate(&a_module);
  warmc_register("A", a);
  WarmInstance *b = warmc_instantiate(&b_module);

  /* B exports a function A defines, and names another as its start.  Both
   * have to be entered with A's instance, so both read A's private global:
   * 4242, plus the one the start function added when B was instantiated. */
  show("reexported_secret", call(b, "reexported_secret", 0, 0));
  show("a_reads_own_secret", call(a, "read_secret", 0, 0));

  show("call_import", call(b, "call_import", 21, 1));
  show("call_indirect_import", call(b, "call_indirect_import", 20, 1));
  /* The same three by tail call, which reaches the other instance without a
   * frame of its own left to hold the pointer. */
  show("tail_call_import", call(b, "tail_call_import", 11, 1));
  show("tail_call_indirect_import", call(b, "tail_call_indirect_import", 12, 1));
  show("tail_secret", call(b, "tail_secret", 0, 0));
  show("read_shared_mem", call(b, "read_shared_mem", 0, 0));
  show("read_answer", call(b, "read_answer", 0, 0));
  show("read_mine", call(b, "read_mine", 0, 0));
  show("read_derived", call(b, "read_derived", 0, 0));
  show("read_at_answer", call(b, "read_at_answer", 0, 0));

  /* A's global, moved from both sides. */
  show("read_counter", call(b, "read_counter", 0, 0));
  show("bump_twice", call(b, "bump_twice", 0, 0));
  show("read_counter_after_bump", call(b, "read_counter", 0, 0));
  call(b, "set_counter", 5, 1);
  show("a_sees_set", call(a, "bump", 0, 0));

  /* One memory, two instances: what B writes, A's export reads back, and a
   * grow from one side moves the size the other side checks against. */
  call(b, "write_shared_mem", 0x2a, 1);
  show("size_before_grow", call(b, "size", 0, 0));
  show("grow", call(b, "grow", 1, 1));
  show("size_after_grow", call(b, "size", 0, 0));
  show("still_reads_data", call(b, "read_shared_mem", 0, 0));

  /* The same crossings from a module whose import pairs are past 32,760
   * bytes: a call, a tail call and a call through a table, each of which
   * reads the pair with its argument already in x0, plus an imported global
   * at the near end of that array and one of our own at the far end.  A's
   * counter was set to 5 and bumped once above, so it reads 6 -- a value
   * this module never wrote, which is the point: the slot holds a pointer
   * into A's instance rather than a copy. */
  WarmInstance *c = warmc_instantiate(&c_module);
  show("wide_call_import", call(c, "wide_call_import", 42, 1));
  show("wide_tail_import", call(c, "wide_tail_import", 22, 1));
  show("wide_indirect_import", call(c, "wide_indirect_import", 32, 1));
  show("wide_imported_global", call(c, "wide_imported_global", 0, 0));
  show("wide_last_global", call(c, "wide_last_global", 0, 0));
  show("wide_first_global", call(c, "wide_first_global", 0, 0));

  /* An exception raised in A and caught in B.  The unwinder has to recognise
   * a return address in one module's code while walking a stack that starts
   * in another's, and the tag the clause names has to resolve through B's
   * instance to the object A raised. */
  show("catch_across", call(b, "catch_across", 7, 1));
  show("catch_across_deep", call(b, "catch_across_deep", 7, 1));
  show("catch_across_wrong_tag", call(b, "catch_across_wrong_tag", 7, 1));
  show("catch_own", call(b, "catch_own", 7, 1));
  /* A clause that names no tag, an exception object handed back to the
   * instance that made it, a frame of A's with a handler list of its own in
   * the middle of the walk, and a region left by a tail call across the
   * boundary before the exception existed. */
  show("catch_across_all", call(b, "catch_across_all", 7, 1));
  show("catch_across_ref", call(b, "catch_across_ref", 7, 1));
  show("catch_across_shielded", call(b, "catch_across_shielded", 7, 1));
  show("catch_across_tail", call(b, "catch_across_tail", 7, 1));
  /* And a chain that alternates between the two instances all the way down,
   * so the walk crosses the boundary at every second frame rather than once. */
  show("catch_across_alt", call(b, "catch_across_alt", 7, 1));
  return 0;
}
